package com.mlserver.inference

import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*
import java.time.Instant
import java.io.File
import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest

data class InferenceRequest(
    val modelId: String,
    val inputTensor: List<Double>,
    val clientId: String,
    val metadata: Map<String, String> = emptyMap()
)

data class InferenceResult(
    val prediction: List<Double>,
    val latencyMs: Long,
    val modelVersion: String
)

class AuditLogger(private val logFile: File) {
    private val buffer = Channel<String>(Channel.BUFFERED)

    suspend fun start() = coroutineScope {
        launch(Dispatchers.IO) {
            for (entry in buffer) {
                logFile.appendText(entry + "\n")
            }
        }
    }

    suspend fun log(level: String, component: String, message: String) {
        val timestamp = Instant.now().toString()
        val sanitizedLevel = level.replace(Regex("[^A-Z]"), "")
        val sanitizedComponent = component.replace(Regex("[^a-zA-Z0-9._-]"), "")
        val sanitizedMessage = message.replace(Regex("[\\r\\n\\t]"), " ")
            .replace(Regex("\\[|\\]"), "")
        val entry = "[$timestamp] [$sanitizedLevel] [$sanitizedComponent] $sanitizedMessage"
        buffer.send(entry)
    }
}

class ModelRegistry {
    private val models = ConcurrentHashMap<String, ModelInfo>()

    data class ModelInfo(
        val version: String,
        val weights: List<Double>,
        val inputDim: Int
    )

    fun register(id: String, info: ModelInfo) {
        models[id] = info
    }

    fun lookup(id: String): ModelInfo? = models[id]
}

class InputValidator {
    fun validateModelId(id: String): Boolean {
        return id.matches(Regex("^[a-zA-Z0-9_-]{1,64}$"))
    }

    fun validateTensor(tensor: List<Double>, expectedDim: Int): Boolean {
        return tensor.size == expectedDim && tensor.all { it.isFinite() }
    }

    fun sanitizeClientId(clientId: String): String {
        return clientId.replace(Regex("[^a-zA-Z0-9@._-]"), "_")
    }
}

class InferenceEngine(
    private val registry: ModelRegistry,
    private val logger: AuditLogger,
    private val validator: InputValidator
) {
    private val requestCounter = ConcurrentHashMap<String, Int>()

    suspend fun processRequest(request: InferenceRequest): Result<InferenceResult> {
        val startTime = System.currentTimeMillis()

        if (!validator.validateModelId(request.modelId)) {
            logger.log("WARN", "inference.engine", 
                "Invalid model ID from client=${validator.sanitizeClientId(request.clientId)}")
            return Result.failure(IllegalArgumentException("Invalid model ID"))
        }

        val model = registry.lookup(request.modelId)
            ?: run {
                logger.log("ERROR", "inference.engine",
                    "Model not found: ${request.modelId}")
                return Result.failure(NoSuchElementException("Model not found"))
            }

        if (!validator.validateTensor(request.inputTensor, model.inputDim)) {
            logger.log("WARN", "inference.engine",
                "Invalid tensor dimensions from client=${validator.sanitizeClientId(request.clientId)}")
            return Result.failure(IllegalArgumentException("Invalid tensor"))
        }

        val traceId = generateTraceId(request)
        logInferenceStart(request, traceId)

        val prediction = withContext(Dispatchers.Default) {
            computeInference(model, request.inputTensor)
        }

        val latency = System.currentTimeMillis() - startTime
        logInferenceComplete(request, traceId, latency)

        return Result.success(InferenceResult(prediction, latency, model.version))
    }

    private fun computeInference(
        model: ModelRegistry.ModelInfo, 
        input: List<Double>
    ): List<Double> {
        return model.weights.chunked(model.inputDim).map { weightRow ->
            weightRow.zip(input).sumOf { (w, x) -> w * x }
        }
    }

    private fun generateTraceId(request: InferenceRequest): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val content = "${request.clientId}:${request.modelId}:${System.nanoTime()}"
        return digest.digest(content.toByteArray())
            .take(8)
            .joinToString("") { "%02x".format(it) }
    }

    private suspend fun logInferenceStart(request: InferenceRequest, traceId: String) {
        val metadataStr = formatMetadata(request.metadata)
        logger.log("INFO", "inference.engine",
            "Starting inference trace=$traceId model=${request.modelId} $metadataStr")
    }

    private suspend fun logInferenceComplete(
        request: InferenceRequest, traceId: String, latencyMs: Long
    ) {
        val count = requestCounter.merge(request.modelId, 1) { a, b -> a + b }
        logger.log("INFO", "inference.engine",
            "Completed inference trace=$traceId latency=${latencyMs}ms total_requests=$count")
    }

    private fun formatMetadata(metadata: Map<String, String>): String {
        if (metadata.isEmpty()) return ""
        return metadata.entries.joinToString(" ") { (k, v) ->
            val safeKey = k.replace(Regex("[^a-zA-Z0-9_]"), "")
            val safeValue = v.replace(Regex("[^a-zA-Z0-9._@:/-]"), "")
            "$safeKey=$safeValue"
        }
    }
}

fun main() = runBlocking {
    val logFile = File("/var/log/ml-inference/audit.log")
    val logger = AuditLogger(logFile)
    val registry = ModelRegistry()
    val validator = InputValidator()

    registry.register("sentiment-v2", ModelRegistry.ModelInfo(
        version = "2.1.0",
        weights = List(30) { it * 0.1 },
        inputDim = 10
    ))

    val engine = InferenceEngine(registry, logger, validator)

    launch { logger.start() }

    val request = InferenceRequest(
        modelId = "sentiment-v2",
        inputTensor = List(10) { it * 0.5 },
        clientId = "user@example.com",
        metadata = mapOf("source" to "api-gateway", "version" to "1.0")
    )

    val result = engine.processRequest(request)
    result.onSuccess { println("Prediction: ${it.prediction}") }
    result.onFailure { println("Error: ${it.message}") }
}
